import { useState, useEffect } from 'react';
import { useAuth } from '../lib/AuthContext';
import {
  mockRequests,
  mockBooks,
  mockUsers,
  BookRequest,
} from '../lib/mockData';

import { requestsApi } from '../lib/api';

import Layout from '../components/Layout';

import {
  Card,
  CardContent,
} from '../components/ui/card';

import {
  Badge,
} from '../components/ui/badge';

import {
  Button,
} from '../components/ui/button';

import {
  Tabs,
  TabsContent,
  TabsList,
  TabsTrigger,
} from '../components/ui/tabs';

import {
  CheckCircle,
  XCircle,
  Clock,
  BookOpen,
  User,
  Calendar,
  RotateCcw,
} from 'lucide-react';

import { toast } from 'sonner';

export default function RequestsPage() {

  const {
    user,
    isApiConnected,
    hasCheckedApi,
  } = useAuth();

  const isLibrarian =
    user?.role === 'librarian';

  const [requests, setRequests] =
    useState<BookRequest[]>([]);

  // ─────────────────────────────────────────────
  // FETCH REQUESTS
  // ─────────────────────────────────────────────

  useEffect(() => {

    if (!hasCheckedApi) return;

    // USE MOCK DATA
    if (!isApiConnected) {

      setRequests(
        isLibrarian
          ? mockRequests
          : mockRequests.filter(
              (r) => r.studentId === user?.id
            )
      );

      return;
    }

    // USE API
    requestsApi
      .list()
      .then((apiRequests) => {

        console.log(
          'REQUESTS:',
          apiRequests
        );

        const mapped: BookRequest[] =
          apiRequests.map((r) => ({

            id: r.id,

            studentId: r.student_id,
            studentName: r.student_name,

            bookId: r.book_id,
            bookTitle: r.book_title,
            bookThumbnail: r.book_thumbnail,

            status: r.status,

            requestDate: r.request_date,
            approvedDate: r.approved_date,
            returnDate: r.return_date,
            dueDate: r.due_date,
          }));

        setRequests(
          isLibrarian
            ? mapped
            : mapped.filter(
                (r) => r.studentId === user?.id
              )
        );
      })
      .catch((err) => {

        console.log(err);

        setRequests(
          isLibrarian
            ? mockRequests
            : mockRequests.filter(
                (r) => r.studentId === user?.id
              )
        );
      });

  }, [
    hasCheckedApi,
    isApiConnected,
    isLibrarian,
    user?.id,
  ]);

  // ─────────────────────────────────────────────
  // APPROVE
  // ─────────────────────────────────────────────

  const handleApprove = async (
    requestId: string
  ) => {

    console.log(
      'APPROVE:',
      requestId
    );

    if (
      hasCheckedApi &&
      isApiConnected
    ) {

      try {

        await requestsApi.approve(
          requestId
        );

      } catch (e: any) {

        console.log(e);

        toast.error(
          e.message ||
          'Failed to approve request'
        );

        return;
      }
    }

    setRequests((prev) =>
      prev.map((req) =>
        req.id === requestId
          ? {
              ...req,

              status: 'approved',

              approvedDate:
                new Date()
                  .toISOString()
                  .split('T')[0],

              dueDate:
                new Date(
                  Date.now() +
                  14 * 24 * 60 * 60 * 1000
                )
                  .toISOString()
                  .split('T')[0],
            }
          : req
      )
    );

    toast.success(
      'Request approved'
    );
  };

  // ─────────────────────────────────────────────
  // DECLINE
  // ─────────────────────────────────────────────

  const handleDecline = async (
    requestId: string
  ) => {

    console.log(
      'DECLINE:',
      requestId
    );

    if (
      hasCheckedApi &&
      isApiConnected
    ) {

      try {

        await requestsApi.decline(
          requestId
        );

      } catch (e: any) {

        console.log(e);

        toast.error(
          e.message ||
          'Failed to decline request'
        );

        return;
      }
    }

    setRequests((prev) =>
      prev.map((req) =>
        req.id === requestId
          ? {
              ...req,
              status: 'declined',
            }
          : req
      )
    );

    toast.success(
      'Request declined'
    );
  };

  // ─────────────────────────────────────────────
  // RETURN
  // ─────────────────────────────────────────────

  const handleMarkReturned =
    async (
      requestId: string
    ) => {

      console.log(
        'RETURN:',
        requestId
      );

      if (
        hasCheckedApi &&
        isApiConnected
      ) {

        try {

          await requestsApi.markReturned(
            requestId
          );

        } catch (e: any) {

          console.log(e);

          toast.error(
            e.message ||
            'Failed to mark as returned'
          );

          return;
        }
      }

      setRequests((prev) =>
        prev.map((req) =>
          req.id === requestId
            ? {
                ...req,
                status: 'returned',

                returnDate:
                  new Date()
                    .toISOString()
                    .split('T')[0],
              }
            : req
        )
      );

      toast.success(
        'Book marked as returned!'
      );
    };

  // ─────────────────────────────────────────────
  // CANCEL
  // ─────────────────────────────────────────────

  const handleCancelRequest =
    async (
      requestId: string
    ) => {

      console.log(
        'CANCEL:',
        requestId
      );

      if (
        hasCheckedApi &&
        isApiConnected
      ) {

        try {

          await requestsApi.cancel(
            requestId
          );

        } catch (e: any) {

          console.log(e);

          toast.error(
            e.message ||
            'Failed to cancel request'
          );

          return;
        }
      }

      setRequests((prev) =>
        prev.filter(
          (req) =>
            req.id !== requestId
        )
      );

      toast.success(
        'Request cancelled'
      );
    };

  // ─────────────────────────────────────────────
  // FILTERS
  // ─────────────────────────────────────────────

  const pendingRequests =
    requests.filter(
      (r) =>
        r.status === 'pending'
    );

  const approvedRequests =
    requests.filter(
      (r) =>
        r.status === 'approved'
    );

  const completedRequests =
    requests.filter(
      (r) =>
        r.status === 'returned'
    );

  const declinedRequests =
    requests.filter(
      (r) =>
        r.status === 'declined'
    );

  // ─────────────────────────────────────────────
  // BADGES
  // ─────────────────────────────────────────────

  const getStatusBadge = (
    status: string
  ) => {

    const map: Record<
      string,
      {
        variant:
          | 'secondary'
          | 'default'
          | 'outline'
          | 'destructive';

        icon: typeof Clock;
      }
    > = {

      pending: {
        variant: 'secondary',
        icon: Clock,
      },

      approved: {
        variant: 'default',
        icon: CheckCircle,
      },

      returned: {
        variant: 'outline',
        icon: CheckCircle,
      },

      declined: {
        variant: 'destructive',
        icon: XCircle,
      },
    };

    const {
      variant,
      icon: Icon,
    } = map[status] ?? map.pending;

    return (
      <Badge
        variant={variant}
        className="gap-1"
      >
        <Icon className="w-3 h-3" />

        {status
          .charAt(0)
          .toUpperCase() +
          status.slice(1)}
      </Badge>
    );
  };

  // ─────────────────────────────────────────────
  // REQUEST CARD
  // ─────────────────────────────────────────────

  const RequestCard = ({
    request,
  }: {
    request: BookRequest;
  }) => {

    const book =
      mockBooks.find(
        (b) =>
          b.id === request.bookId
      );

    const student =
      mockUsers.find(
        (u) =>
          u.id === request.studentId
      );

    const isOverdue =
      request.status ===
        'approved' &&
      request.dueDate &&
      new Date(request.dueDate) <
        new Date();

    const thumbnail =
      request.bookThumbnail ??
      book?.thumbnail;

    const title =
      request.bookTitle ??
      book?.title ??
      'Unknown Book';

    const studentName =
      request.studentName ??
      student?.name ??
      'Unknown Student';

    return (
      <Card className="hover:shadow-md transition-shadow">

        <CardContent className="p-4 sm:p-6">

          <div className="flex flex-col sm:flex-row gap-4">

            <div className="shrink-0">

              <img
                src={thumbnail}
                alt={title}
                className="w-full sm:w-24 h-32 sm:h-32 object-cover rounded-lg"
              />

            </div>

            <div className="flex-1 space-y-3 min-w-0">

              <div>

                <div className="flex flex-wrap items-start justify-between gap-2">

                  <h3 className="font-semibold text-base sm:text-lg truncate">
                    {title}
                  </h3>

                  {getStatusBadge(
                    request.status
                  )}

                </div>

                <p className="text-sm text-muted-foreground">
                  {book?.author}
                </p>

              </div>

              <div className="grid grid-cols-1 sm:grid-cols-2 gap-2 text-sm">

                {isLibrarian && (

                  <div className="flex items-center gap-2 text-muted-foreground">

                    <User className="w-4 h-4 shrink-0" />

                    <span className="truncate">
                      {studentName}
                    </span>

                  </div>

                )}

                <div className="flex items-center gap-2 text-muted-foreground">

                  <Calendar className="w-4 h-4 shrink-0" />

                  <span>
                    Requested:
                    {' '}
                    {new Date(
                      request.requestDate
                    ).toLocaleDateString()}
                  </span>

                </div>

                {request.dueDate && (

                  <div
                    className={`flex items-center gap-2 ${
                      isOverdue
                        ? 'text-red-600 font-medium'
                        : 'text-muted-foreground'
                    }`}
                  >

                    <Clock className="w-4 h-4 shrink-0" />

                    <span>

                      Due:
                      {' '}
                      {new Date(
                        request.dueDate
                      ).toLocaleDateString()}

                      {isOverdue &&
                        ' — Overdue!'}

                    </span>

                  </div>

                )}

                {request.returnDate && (

                  <div className="flex items-center gap-2 text-muted-foreground">

                    <CheckCircle className="w-4 h-4 shrink-0" />

                    <span>

                      Returned:
                      {' '}
                      {new Date(
                        request.returnDate
                      ).toLocaleDateString()}

                    </span>

                  </div>

                )}

              </div>

              <div className="flex flex-wrap gap-2 pt-1">

                {isLibrarian ? (
                  <>

                    {request.status ===
                      'pending' && (
                      <>

                        <Button
                          size="sm"
                          className="bg-green-600 hover:bg-green-700"
                          onClick={() =>
                            handleApprove(
                              request.id
                            )
                          }
                        >

                          <CheckCircle className="w-4 h-4 mr-1" />

                          Approve

                        </Button>

                        <Button
                          size="sm"
                          variant="destructive"
                          onClick={() =>
                            handleDecline(
                              request.id
                            )
                          }
                        >

                          <XCircle className="w-4 h-4 mr-1" />

                          Decline

                        </Button>

                      </>
                    )}

                    {request.status ===
                      'approved' && (

                      <Button
                        size="sm"
                        variant="outline"
                        onClick={() =>
                          handleMarkReturned(
                            request.id
                          )
                        }
                      >

                        <RotateCcw className="w-4 h-4 mr-1" />

                        Mark as Returned

                      </Button>

                    )}

                  </>
                ) : (
                  <>

                    {request.status ===
                      'pending' && (

                      <Button
                        size="sm"
                        variant="outline"
                        onClick={() =>
                          handleCancelRequest(
                            request.id
                          )
                        }
                      >

                        <XCircle className="w-4 h-4 mr-1" />

                        Cancel Request

                      </Button>

                    )}

                    {request.status ===
                      'approved' && (

                      <Button
                        size="sm"
                        className="bg-green-600 hover:bg-green-700 text-white"
                        onClick={() =>
                          handleMarkReturned(
                            request.id
                          )
                        }
                      >

                        <RotateCcw className="w-4 h-4 mr-1" />

                        Return Book

                      </Button>

                    )}

                  </>
                )}

              </div>

            </div>

          </div>

        </CardContent>

      </Card>
    );
  };

  // ─────────────────────────────────────────────
  // EMPTY STATE
  // ─────────────────────────────────────────────

  const EmptyState = ({
    message,
  }: {
    message: string;
  }) => (

    <Card>

      <CardContent className="p-12 text-center">

        <BookOpen className="w-12 h-12 mx-auto text-muted-foreground mb-3" />

        <p className="text-muted-foreground">
          {message}
        </p>

      </CardContent>

    </Card>
  );

  // ─────────────────────────────────────────────
  // UI
  // ─────────────────────────────────────────────

  return (
    <Layout>

      <div className="space-y-6">

        <div>

          <h1 className="text-2xl sm:text-3xl font-bold text-foreground">

            {isLibrarian
              ? 'Manage Requests'
              : 'My Requests'}

          </h1>

          <p className="text-muted-foreground mt-1">

            {isLibrarian
              ? 'Review and manage book requests from students'
              : 'Track your book borrowing requests'}

          </p>

        </div>

        <div className="grid grid-cols-2 sm:grid-cols-4 gap-3 sm:gap-4">

          {[
            {
              count:
                pendingRequests.length,
              label: 'Pending',
              color:
                'text-yellow-600',
            },
            {
              count:
                approvedRequests.length,
              label: 'Approved',
              color:
                'text-green-600',
            },
            {
              count:
                completedRequests.length,
              label: 'Completed',
              color:
                'text-blue-600',
            },
            {
              count:
                declinedRequests.length,
              label: 'Declined',
              color:
                'text-red-600',
            },
          ].map(
            ({
              count,
              label,
              color,
            }) => (

              <Card key={label}>

                <CardContent className="p-4 text-center">

                  <div
                    className={`text-2xl sm:text-3xl font-bold ${color}`}
                  >
                    {count}
                  </div>

                  <div className="text-xs sm:text-sm text-muted-foreground mt-1">
                    {label}
                  </div>

                </CardContent>

              </Card>
            )
          )}

        </div>

        <Tabs
          defaultValue="pending"
          className="space-y-4"
        >

          <TabsList className="grid w-full grid-cols-2 sm:grid-cols-4">

            <TabsTrigger value="pending">
              Pending (
              {pendingRequests.length}
              )
            </TabsTrigger>

            <TabsTrigger value="approved">
              Approved (
              {approvedRequests.length}
              )
            </TabsTrigger>

            <TabsTrigger value="completed">
              Completed (
              {completedRequests.length}
              )
            </TabsTrigger>

            <TabsTrigger value="declined">
              Declined (
              {declinedRequests.length}
              )
            </TabsTrigger>

          </TabsList>

          <TabsContent
            value="pending"
            className="space-y-4"
          >

            {pendingRequests.length === 0
              ? (
                <EmptyState message="No pending requests" />
              )
              : pendingRequests.map(
                  (r) => (
                    <RequestCard
                      key={r.id}
                      request={r}
                    />
                  )
                )}

          </TabsContent>

          <TabsContent
            value="approved"
            className="space-y-4"
          >

            {approvedRequests.length === 0
              ? (
                <EmptyState message="No approved requests" />
              )
              : approvedRequests.map(
                  (r) => (
                    <RequestCard
                      key={r.id}
                      request={r}
                    />
                  )
                )}

          </TabsContent>

          <TabsContent
            value="completed"
            className="space-y-4"
          >

            {completedRequests.length === 0
              ? (
                <EmptyState message="No completed requests" />
              )
              : completedRequests.map(
                  (r) => (
                    <RequestCard
                      key={r.id}
                      request={r}
                    />
                  )
                )}

          </TabsContent>

          <TabsContent
            value="declined"
            className="space-y-4"
          >

            {declinedRequests.length === 0
              ? (
                <EmptyState message="No declined requests" />
              )
              : declinedRequests.map(
                  (r) => (
                    <RequestCard
                      key={r.id}
                      request={r}
                    />
                  )
                )}

          </TabsContent>

        </Tabs>

      </div>

    </Layout>
  );
}

import { useState, useEffect } from 'react';
import { useAuth } from '../lib/AuthContext';
import { mockBooks, mockRequests, mockFines, Book, BookRequest } from '../lib/mockData';
import { booksApi, requestsApi, finesApi, ApiBook, ApiRequest, ApiFine } from '../lib/api';
import Layout from '../components/Layout';
import BookCard from '../components/BookCard';
import { Card, CardContent, CardHeader, CardTitle } from '../components/ui/card';
import { Dialog, DialogContent, DialogHeader, DialogTitle, DialogDescription } from '../components/ui/dialog';
import { BookOpen, FileText, DollarSign, Clock } from 'lucide-react';
import { Button } from '../components/ui/button';
import { toast } from 'sonner';

export default function StudentDashboard() {
  const { user, isApiConnected, hasCheckedApi } = useAuth();
  const [selectedBook, setSelectedBook] = useState<Book | null>(null);
  const [books, setBooks] = useState<Book[]>([]);
  const [requests, setRequests] = useState<BookRequest[]>([]);
  const [fines, setFines] = useState<ApiFine[]>([]);

  useEffect(() => {
    if (!hasCheckedApi || !user) return;

    if (isApiConnected) {
      booksApi.list()
        .then((apiBooks) => {
          setBooks(
            apiBooks.map((b) => ({
              id: b.id,
              title: b.title,
              author: b.author,
              category: b.category,
              isbn: b.isbn,
              quantity: b.quantity,
              availableQuantity: b.available_quantity,
              description: b.description,
              image: b.image,
              thumbnail: b.thumbnail,
              publishedDate: b.published_date,
            }))
          );
        })
        .catch(() => {
          setBooks(mockBooks.slice(0, 4));
        });

      requestsApi.list()
        .then((apiRequests) => {
          setRequests(
            apiRequests.map((r) => ({
              id: r.id,
              studentId: r.student_id,
              bookId: r.book_id,
              requestType: r.request_type,
              status: r.status,
              requestDate: r.request_date,
              approvedDate: r.approved_date,
              returnDate: r.return_date,
              dueDate: r.due_date,
            }))
          );
        })
        .catch(() => {
          setRequests(mockRequests.filter((r) => r.studentId === user?.id));
        });

      finesApi.list()
        .then((apiFines) => {
          setFines(
            apiFines.map((fine) => ({
              id: fine.id,
              studentId: fine.student_id,
              amount: fine.amount,
              status: fine.status,
              paymentDate: fine.payment_date,
              reason: fine.reason,
            }))
          );
        })
        .catch(() => {
          setFines(mockFines.filter((f) => f.studentId === user?.id));
        });
    } else {
      setBooks(mockBooks.slice(0, 4));
      setRequests(mockRequests.filter((r) => r.studentId === user?.id));
      setFines(mockFines.filter((f) => f.studentId === user?.id));
    }
  }, [hasCheckedApi, isApiConnected, user]);

  const userRequests = requests.filter((r) => r.studentId === user?.id);
  const issuedBooks = userRequests.filter((r) => r.status === 'approved').length;
  const pendingRequests = userRequests.filter((r) => r.status === 'pending').length;
  const returnedBooks = userRequests.filter((r) => r.status === 'returned').length;
  const totalFines = fines.filter((f) => f.status === 'pending').reduce((sum, f) => sum + f.amount, 0);

  const recentBooks = books.slice(0, 4);

  const handleRequestBook = async (book: Book) => {
    if (!hasCheckedApi || isApiConnected) {
      try {
        const apiReq = await requestsApi.create(book.id);
        const newReq: BookRequest = {
          id: apiReq.id,
          studentId: apiReq.student_id,
          bookId: apiReq.book_id,
          requestType: apiReq.request_type,
          status: apiReq.status,
          requestDate: apiReq.request_date,
          approvedDate: apiReq.approved_date,
          returnDate: apiReq.return_date,
          dueDate: apiReq.due_date,
        };
        setRequests((prev) => [...prev, newReq]);
        toast.success(`Request submitted for "${book.title}"`);
        setSelectedBook(null);
        return;
      } catch (e: any) {
        toast.error(e.message || 'Failed to submit request');
        return;
      }
    }

    const newReq: BookRequest = {
      id: `req_${Date.now()}`,
      studentId: user!.id,
      bookId: book.id,
      requestType: 'issue',
      status: 'pending',
      requestDate: new Date().toISOString().split('T')[0],
    };
    setRequests((prev) => [...prev, newReq]);
    toast.success(`Request submitted for "${book.title}"`);
    setSelectedBook(null);
  };

  const stats = [
    {
      icon: BookOpen,
      label: 'Issued Books',
      value: issuedBooks,
      color: 'text-blue-600 bg-blue-100',
    },
    {
      icon: FileText,
      label: 'Pending Requests',
      value: pendingRequests,
      color: 'text-yellow-600 bg-yellow-100',
    },
    {
      icon: Clock,
      label: 'Returned Books',
      value: returnedBooks,
      color: 'text-green-600 bg-green-100',
    },
    {
      icon: DollarSign,
      label: 'Total Fines',
      value: `$${totalFines.toFixed(2)}`,
      color: 'text-red-600 bg-red-100',
    },
  ];

  return (
    <Layout>
      <div className="space-y-6">
        <div>
          <h1 className="text-2xl sm:text-3xl font-bold text-foreground">Welcome back, {user?.name}!</h1>
          <p className="text-sm sm:text-base text-muted-foreground mt-1">Here's your library activity overview</p>
        </div>

        <div className="grid grid-cols-2 lg:grid-cols-4 gap-3 sm:gap-4">
          {stats.map((stat) => (
            <Card key={stat.label} className="hover:shadow-md transition-shadow">
              <CardContent className="p-4 sm:p-6">
                <div className="flex flex-col sm:flex-row items-start sm:items-center gap-3 sm:gap-4">
                  <div className={`p-2 sm:p-3 rounded-full ${stat.color} shrink-0`}>
                    <stat.icon className="w-5 h-5 sm:w-6 sm:h-6" />
                  </div>
                  <div className="min-w-0">
                    <p className="text-xs sm:text-sm text-muted-foreground truncate">{stat.label}</p>
                    <p className="text-xl sm:text-2xl font-bold">{stat.value}</p>
                  </div>
                </div>
              </CardContent>
            </Card>
          ))}
        </div>

        <Card>
          <CardHeader>
            <CardTitle className="text-lg sm:text-xl">Recent Additions</CardTitle>
          </CardHeader>
          <CardContent>
            <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-4">
              {recentBooks.map((book) => (
                <BookCard
                  key={book.id}
                  book={book}
                  onView={setSelectedBook}
                  onRequest={handleRequestBook}
                />
              ))}
            </div>
          </CardContent>
        </Card>

        {selectedBook && (
          <Dialog open={!!selectedBook} onOpenChange={() => setSelectedBook(null)}>
            <DialogContent className="max-w-3xl max-h-[90vh] overflow-y-auto">
              <DialogHeader>
                <DialogTitle className="text-2xl">{selectedBook.title}</DialogTitle>
                <DialogDescription>by {selectedBook.author}</DialogDescription>
              </DialogHeader>
              <div className="grid md:grid-cols-2 gap-6 mt-4">
                <div className="relative aspect-[3/4] rounded-lg overflow-hidden bg-muted">
                  <img
                    src={selectedBook.image}
                    alt={selectedBook.title}
                    className="w-full h-full object-cover"
                  />
                </div>
                <div className="space-y-4">
                  <div>
                    <h3 className="font-semibold mb-2">Description</h3>
                    <p className="text-muted-foreground">{selectedBook.description}</p>
                  </div>
                  <div className="space-y-2">
                    <div className="flex justify-between">
                      <span className="text-muted-foreground">Category:</span>
                      <span className="font-medium">{selectedBook.category}</span>
                    </div>
                    <div className="flex justify-between">
                      <span className="text-muted-foreground">ISBN:</span>
                      <span className="font-medium">{selectedBook.isbn}</span>
                    </div>
                    <div className="flex justify-between">
                      <span className="text-muted-foreground">Published:</span>
                      <span className="font-medium">
                        {new Date(selectedBook.publishedDate).toLocaleDateString()}
                      </span>
                    </div>
                    <div className="flex justify-between">
                      <span className="text-muted-foreground">Available:</span>
                      <span className="font-medium">
                        {selectedBook.availableQuantity} of {selectedBook.quantity}
                      </span>
                    </div>
                  </div>
                  <Button
                    className="w-full bg-primary hover:bg-primary/90"
                    disabled={selectedBook.availableQuantity === 0}
                    onClick={() => handleRequestBook(selectedBook)}
                  >
                    {selectedBook.availableQuantity > 0 ? 'Request This Book' : 'Not Available'}
                  </Button>
                </div>
              </div>
            </DialogContent>
          </Dialog>
        )}
      </div>
    </Layout>
  );
}

import { useState } from 'react';
import { mockUsers, mockRequests, User } from '../lib/mockData';
import Layout from '../components/Layout';
import { Card, CardContent } from '../components/ui/card';
import { Button } from '../components/ui/button';
import { Input } from '../components/ui/input';
import { Avatar, AvatarImage, AvatarFallback } from '../components/ui/avatar';
import { Badge } from '../components/ui/badge';
import { Dialog, DialogContent, DialogHeader, DialogTitle, DialogDescription } from '../components/ui/dialog';
import { Search, Mail, Phone, BookOpen, Ban, UserCheck } from 'lucide-react';
import { toast } from 'sonner';

export default function UsersPage() {
  const [users, setUsers] = useState(mockUsers.filter((u) => u.role === 'student'));
  const [searchQuery, setSearchQuery] = useState('');
  const [selectedUser, setSelectedUser] = useState<User | null>(null);

  const filteredUsers = users.filter(
    (user) =>
      user.name.toLowerCase().includes(searchQuery.toLowerCase()) ||
      user.email.toLowerCase().includes(searchQuery.toLowerCase())
  );

  const handleSuspend = (userId: string) => {
    toast.success('User suspended successfully');
  };

  const handleActivate = (userId: string) => {
    toast.success('User activated successfully');
  };

  const getUserStats = (userId: string) => {
    const userRequests = mockRequests.filter((r) => r.studentId === userId);
    return {
      totalBorrowed: userRequests.filter((r) => r.status === 'approved').length,
      pending: userRequests.filter((r) => r.status === 'pending').length,
      returned: userRequests.filter((r) => r.status === 'returned').length,
    };
  };

  return (
    <Layout>
      <div className="space-y-6">
        <div>
          <h1 className="text-2xl sm:text-3xl font-bold text-foreground">Manage Users</h1>
          <p className="text-muted-foreground mt-1">View and manage student accounts</p>
        </div>

        <div className="relative">
          <Search className="absolute left-3 top-1/2 transform -translate-y-1/2 w-4 h-4 text-muted-foreground" />
          <Input
            placeholder="Search by name or email..."
            value={searchQuery}
            onChange={(e) => setSearchQuery(e.target.value)}
            className="pl-10 h-11"
          />
        </div>

        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-4">
          {filteredUsers.map((user) => {
            const stats = getUserStats(user.id);
            return (
              <Card
                key={user.id}
                className="hover:shadow-md transition-shadow cursor-pointer"
                onClick={() => setSelectedUser(user)}
              >
                <CardContent className="p-6">
                  <div className="flex items-start gap-4">
                    <Avatar className="w-16 h-16 shrink-0">
                      <AvatarImage src={user.profileImage} />
                      <AvatarFallback className="bg-primary text-white text-lg">
                        {user.name.charAt(0)}
                      </AvatarFallback>
                    </Avatar>
                    <div className="flex-1 min-w-0">
                      <div className="flex items-start justify-between gap-2">
                        <div className="min-w-0">
                          <h3 className="font-semibold truncate">{user.name}</h3>
                          <p className="text-sm text-muted-foreground truncate">{user.email}</p>
                        </div>
                        <Badge variant="default" className="shrink-0">
                          Active
                        </Badge>
                      </div>

                      <div className="mt-4 grid grid-cols-3 gap-2 text-center">
                        <div>
                          <div className="text-lg font-bold text-primary">{stats.totalBorrowed}</div>
                          <div className="text-xs text-muted-foreground">Borrowed</div>
                        </div>
                        <div>
                          <div className="text-lg font-bold text-yellow-600">{stats.pending}</div>
                          <div className="text-xs text-muted-foreground">Pending</div>
                        </div>
                        <div>
                          <div className="text-lg font-bold text-green-600">{stats.returned}</div>
                          <div className="text-xs text-muted-foreground">Returned</div>
                        </div>
                      </div>
                    </div>
                  </div>
                </CardContent>
              </Card>
            );
          })}
        </div>

        {filteredUsers.length === 0 && (
          <Card>
            <CardContent className="p-12 text-center">
              <p className="text-muted-foreground">No users found matching your search.</p>
            </CardContent>
          </Card>
        )}

        {selectedUser && (
          <Dialog open={!!selectedUser} onOpenChange={() => setSelectedUser(null)}>
            <DialogContent className="max-w-2xl">
              <DialogHeader>
                <DialogTitle>User Details</DialogTitle>
                <DialogDescription>View detailed user information and borrowing activity</DialogDescription>
              </DialogHeader>
              <div className="space-y-6 mt-4">
                <div className="flex flex-col sm:flex-row items-center sm:items-start gap-6">
                  <Avatar className="w-24 h-24">
                    <AvatarImage src={selectedUser.profileImage} />
                    <AvatarFallback className="bg-primary text-white text-2xl">
                      {selectedUser.name.charAt(0)}
                    </AvatarFallback>
                  </Avatar>
                  <div className="flex-1 text-center sm:text-left">
                    <h2 className="text-2xl font-bold">{selectedUser.name}</h2>
                    <Badge variant="default" className="mt-2">
                      Active Student
                    </Badge>
                  </div>
                </div>

                <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
                  <div className="space-y-3">
                    <div className="flex items-center gap-3 p-3 bg-secondary/30 rounded-lg">
                      <Mail className="w-5 h-5 text-muted-foreground shrink-0" />
                      <div className="min-w-0">
                        <p className="text-xs text-muted-foreground">Email</p>
                        <p className="font-medium truncate">{selectedUser.email}</p>
                      </div>
                    </div>
                    <div className="flex items-center gap-3 p-3 bg-secondary/30 rounded-lg">
                      <Phone className="w-5 h-5 text-muted-foreground shrink-0" />
                      <div className="min-w-0">
                        <p className="text-xs text-muted-foreground">Phone</p>
                        <p className="font-medium">{selectedUser.phone || 'Not provided'}</p>
                      </div>
                    </div>
                  </div>

                  <div className="space-y-3">
                    <div className="p-3 bg-secondary/30 rounded-lg">
                      <div className="flex items-center gap-2 mb-2">
                        <BookOpen className="w-5 h-5 text-primary" />
                        <p className="text-xs text-muted-foreground">Borrowing Activity</p>
                      </div>
                      <div className="grid grid-cols-3 gap-2 text-center">
                        {Object.entries(getUserStats(selectedUser.id)).map(([key, value]) => (
                          <div key={key}>
                            <div className="text-xl font-bold text-primary">{value}</div>
                            <div className="text-xs text-muted-foreground capitalize">
                              {key.replace('total', '')}
                            </div>
                          </div>
                        ))}
                      </div>
                    </div>
                  </div>
                </div>

                <div className="flex flex-col sm:flex-row gap-3 pt-4">
                  <Button variant="outline" className="flex-1" onClick={() => setSelectedUser(null)}>
                    Close
                  </Button>
                  <Button
                    variant="outline"
                    className="flex-1"
                    onClick={() => handleSuspend(selectedUser.id)}
                  >
                    <Ban className="w-4 h-4 mr-2" />
                    Suspend Account
                  </Button>
                  <Button
                    className="flex-1 bg-primary hover:bg-primary/90"
                    onClick={() => handleActivate(selectedUser.id)}
                  >
                    <UserCheck className="w-4 h-4 mr-2" />
                    Activate Account
                  </Button>
                </div>
              </div>
            </DialogContent>
          </Dialog>
        )}
      </div>
    </Layout>
  );
}

@custom-variant dark (&:is(.dark *));

:root {
  --font-size: 16px;
  /* 60-30-10 Color Rule: 60% White, 30% Blue, 10% Yellow */
  --background: #ffffff;
  --foreground: #1e293b;
  --card: #ffffff;
  --card-foreground: #1e293b;
  --popover: #ffffff;
  --popover-foreground: #1e293b;
  /* Primary Blue (30%) */
  --primary: #2563eb;
  --primary-foreground: #ffffff;
  /* Secondary Blue Shades */
  --secondary: #eff6ff;
  --secondary-foreground: #1e40af;
  --muted: #f1f5f9;
  --muted-foreground: #64748b;
  /* Accent Yellow (10%) */
  --accent: #fbbf24;
  --accent-foreground: #1e293b;
  --destructive: #dc2626;
  --destructive-foreground: #ffffff;
  --border: #e2e8f0;
  --input: transparent;
  --input-background: #f8fafc;
  --switch-background: #cbd5e1;
  --font-weight-medium: 500;
  --font-weight-normal: 400;
  --ring: #2563eb;
  --chart-1: #2563eb;
  --chart-2: #3b82f6;
  --chart-3: #60a5fa;
  --chart-4: #fbbf24;
  --chart-5: #f59e0b;
  --radius: 0.625rem;
  /* Sidebar Blue Theme */
  --sidebar: #1e40af;
  --sidebar-foreground: #ffffff;
  --sidebar-primary: #fbbf24;
  --sidebar-primary-foreground: #1e293b;
  --sidebar-accent: #2563eb;
  --sidebar-accent-foreground: #ffffff;
  --sidebar-border: #1e3a8a;
  --sidebar-ring: #fbbf24;
}

.dark {
